/** The one airframe this simulator flies. */
export interface AircraftModel {
  label: string;
  /** glTF generated by scripts/make-mq9.mjs at published dimensions. */
  uri: string;
  scale: number;
  minimumPixelSize: number;
  /**
   * Radians added to hpr.heading so the nose leads the flight path.
   *
   * Cesium maps a glTF's +Z axis onto its local +X, and at heading 0 that
   * points east — so a model built nose-along-+Z needs -90 deg to read as a
   * compass bearing.
   */
  noseOffset: number;
}

export const MQ9_MODEL: AircraftModel = {
  label: "MQ-9 Reaper",
  uri: `${import.meta.env.BASE_URL}models/MQ-9_Reaper.gltf`,
  scale: 1,
  minimumPixelSize: 56,
  noseOffset: -Math.PI / 2,
};
